/**
 * @file bufrt.c
 * @brief The buffer substrate behind std::data::buf: carve, give, reserve, release, discard.
 *
 * The block is emitted only when the program declares extern!("extc-buf"), which only
 * stdlib/std/data/buf.extc does (the declaration site is the trigger); a program with no
 * buf never carries it, and it never drags in the reclamation runtime either (a buffer
 * storage is foreign memory, not an rc slot, so a T0 program that uses one stays T0).
 */
#include "bufrt.h"
/**
 * @brief Emit the buffer substrate into the generated C.
 *
 * The text is one fixed block: the per-process virtual-address arena, carve and give, reserve
 * and release, discard, and the span lookup the library uses to account a reservation by the
 * block it actually got. Strategy stays in std::data::buf; this side holds no policy.
 */

void bufRtEmitRuntime(Arena *a, Buf *out) {
    (void)a;
    bufPuts(out, "\n/* ---- buffer substrate (std::data::buf) [rt:buf] ----\n *\n * A buffer keeps ONE reservation of address space, 2 MiB aligned, inside a shared arena of\n * buddy-allocated 2 MiB quanta. Reserving costs a few nanoseconds (tools/probe/vaarena.c\n * times a carve at 7 ns against 1,897 ns for a dedicated mmap), and no page is resident until a\n * writer touches it, so a reservation is address space, not memory. Growing inside the\n * reservation therefore costs one first-touch fault per page written and copies nothing; a kind\n * that runs out of its reservation asks for a bigger one and moves once.\n *\n * Why these three entry points belong to the compiler and not to extC: aligning a range up to\n * 2 MiB, advising it MADV_HUGEPAGE, and folding an interior address back to its page need\n * pointer arithmetic and integer-to-pointer conversion, both of which the language refuses.\n * Every policy question -- how much to reserve, when to grow, when to move, how long the buffer\n * is -- stays in stdlib/std/data/buf.extc.\n */\n#ifndef EXTC_BUF_HUGE\n#define EXTC_BUF_HUGE ((size_t)2097152)   /* the alignment, and the huge-page quantum madvise promotes */\n#endif\n#ifndef EXTC_BUF_QSHIFT\n#define EXTC_BUF_QSHIFT 21                 /* 2 MiB quanta: every carved range is aligned for huge pages */\n#endif\n#ifndef EXTC_BUF_ORD\n#define EXTC_BUF_ORD 15                    /* 32768 quanta = 64 GiB of address space per arena */\n#endif\n#ifndef EXTC_BUF_ARENAS\n#define EXTC_BUF_ARENAS 8                  /* 512 GiB in total, created lazily one arena at a time */\n#endif\n#ifndef EXTC_BUF_HUGE_MIN\n#define EXTC_BUF_HUGE_MIN ((size_t)4194304) /* only a range this large is advised huge: below it the tail page wastes RSS for too little gain (on the reclamation side, advising every range costs 5.7 -> 7.4 MB of RSS) */\n#endif\n#if defined(__linux__) || defined(__APPLE__)\n#define EXTC_BUF_MMAP_OK 1\n#else\n#define EXTC_BUF_MMAP_OK 0\n#endif\n#if EXTC_BUF_MMAP_OK\n#ifndef PROT_NONE\n#define PROT_NONE 0x0\n#endif\n#ifndef PROT_READ\n#define PROT_READ 0x1\n#endif\n#ifndef PROT_WRITE\n#define PROT_WRITE 0x2\n#endif\n#ifndef MAP_PRIVATE\n#define MAP_PRIVATE 0x02\n#endif\n#ifndef MAP_ANONYMOUS\n#define MAP_ANONYMOUS 0x20\n#endif\n#ifndef MAP_NORESERVE\n#define MAP_NORESERVE 0x4000\n#endif\n#ifndef MADV_HUGEPAGE\n#define MADV_HUGEPAGE 14\n#endif\n#ifndef MADV_DONTNEED\n#define MADV_DONTNEED 4\n#endif\n#endif\n/* <sys/mman.h> is not included on purpose: the stdlib declares its own mmap for plates, and\n * this declaration matches that one, so a program using both compiles. */\nextern uint8_t *mmap(void *, uint64_t, int32_t, int32_t, int32_t, int64_t);\nextern int32_t munmap(void *, uint64_t);\nextern int madvise(void *, size_t, int);\n\ntypedef struct ExtcBufArena {\n    char    *base;\n    int32_t  fl[EXTC_BUF_ORD + 1];   /* free list per order: the quantum index of the head */\n    int32_t *nextQ;                  /* next block in the same free list, per quantum */\n    int32_t *prevQ;                  /* previous block in the same free list; -1 at the head */\n    uint8_t *startQ;                 /* per quantum: 1 = this quantum begins a block, interior stays 0 */\n    uint8_t *ordQ;                   /* per block start: bit 7 = free, low bits = the order */\n} ExtcBufArena;\nstatic ExtcBufArena extc_buf_arena[EXTC_BUF_ARENAS];\nstatic int extc_buf_nArena;\nstatic long long extc_buf_liveBytes, extc_buf_calls, extc_buf_fails;\nstatic int extc_buf_lock;\n\n__attribute__((unused)) static void extc_buf_lockAcq(void) { while (__atomic_exchange_n(&extc_buf_lock, 1, __ATOMIC_ACQUIRE)) { } }\n__attribute__((unused)) static void extc_buf_lockRel(void) { __atomic_store_n(&extc_buf_lock, 0, __ATOMIC_RELEASE); }\n\n/* The free lists are doubly linked, and a block start is one bit in `startQ`, so both halves of\n * an allocation are O(1) in the size of the arena: the twin leaves its list by a pointer splice,\n * and a split writes two marks instead of marking every quantum of the block as interior. The\n * first version scanned the list and painted the interior, which cost 0.76 s for the 100k\n * short-lived buffers of bench/buf s2 -- three orders of magnitude over the 7 ns a carve was\n * accounted for, and invisible on any workload whose buffers grow instead of churning. */\n__attribute__((unused)) static void extc_buf_flPush(ExtcBufArena *a, int32_t b, int k) {\n    a->nextQ[b] = a->fl[k];\n    a->prevQ[b] = -1;\n    if (a->fl[k] >= 0) a->prevQ[a->fl[k]] = b;\n    a->fl[k] = b;\n}\n__attribute__((unused)) static void extc_buf_flPop(ExtcBufArena *a, int32_t b, int k) {\n    int32_t prv = a->prevQ[b], nxt = a->nextQ[b];\n    if (prv < 0) a->fl[k] = nxt; else a->nextQ[prv] = nxt;\n    if (nxt >= 0) a->prevQ[nxt] = prv;\n    a->prevQ[b] = -1;\n    a->nextQ[b] = -1;\n}\n\n__attribute__((unused)) static int extc_buf_arenaNew(void) {\n    size_t q = (size_t)1 << EXTC_BUF_QSHIFT;\n    size_t span = ((size_t)1 << EXTC_BUF_ORD) << EXTC_BUF_QSHIFT;\n    uint8_t *raw;\n    char *base;\n    ExtcBufArena *a;\n    if (extc_buf_nArena >= EXTC_BUF_ARENAS) return 0;\n    raw = mmap((void *)0, (uint64_t)(span + q), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, (int64_t)0);\n    if (raw == (uint8_t *)0 || raw == (uint8_t *)-1) return 0;\n    base = (char *)(((uintptr_t)raw + (q - 1)) & ~(uintptr_t)(q - 1));   /* at most 2 MiB of head stays mapped: harmless, and it is the only way without MAP_FIXED */\n    a = &extc_buf_arena[extc_buf_nArena];\n    a->nextQ = (int32_t *)calloc((size_t)1 << EXTC_BUF_ORD, sizeof(int32_t));\n    a->prevQ = (int32_t *)calloc((size_t)1 << EXTC_BUF_ORD, sizeof(int32_t));\n    a->startQ = (uint8_t *)calloc((size_t)1 << EXTC_BUF_ORD, sizeof(uint8_t));\n    a->ordQ = (uint8_t *)calloc((size_t)1 << EXTC_BUF_ORD, sizeof(uint8_t));\n    if (!a->nextQ || !a->prevQ || !a->startQ || !a->ordQ) {\n        free(a->nextQ);\n        free(a->prevQ);\n        free(a->startQ);\n        free(a->ordQ);\n        a->nextQ = (int32_t *)0;\n        a->prevQ = (int32_t *)0;\n        a->startQ = (uint8_t *)0;\n        a->ordQ = (uint8_t *)0;\n        return 0;\n    }\n    a->base = base;\n    for (int i = 0; i <= EXTC_BUF_ORD; i++) a->fl[i] = -1;\n    a->fl[EXTC_BUF_ORD] = 0;\n    a->startQ[0] = 1;\n    a->ordQ[0] = (uint8_t)(EXTC_BUF_ORD | 0x80);\n    extc_buf_nArena++;\n    return 1;\n}\n\n/* Carve a range of at least need bytes; the range is a power of two of 2 MiB quanta, so its size\n * can exceed need by up to almost 2x. 0 means \"no arena could serve it\". */\n__attribute__((unused)) static char *extc_buf_carve(size_t need) {\n    size_t q = (size_t)1 << EXTC_BUF_QSHIFT;\n    size_t nq = (need + q - 1) >> EXTC_BUF_QSHIFT;\n    int ord = 0;\n    extc_buf_calls++;\n    if (nq == 0) nq = 1;\n    if (nq > ((size_t)1 << EXTC_BUF_ORD)) { extc_buf_fails++; return (char *)0; }\n    while ((((size_t)1 << ord) < nq) && ord < EXTC_BUF_ORD) ord++;\n    for (int attempt = 0; attempt < 2; attempt++) {\n        for (int i = 0; i < extc_buf_nArena; i++) {\n            ExtcBufArena *a = &extc_buf_arena[i];\n            int k = ord;\n            int32_t b;\n            while (k <= EXTC_BUF_ORD && a->fl[k] < 0) k++;\n            if (k > EXTC_BUF_ORD) continue;\n            b = a->fl[k];\n            extc_buf_flPop(a, b, k);\n            while (k > ord) {   /* split down to the requested order: the upper half stays free */\n                int32_t half;\n                k--;\n                half = b + ((int32_t)1 << k);\n                a->startQ[half] = 1;\n                a->ordQ[half] = (uint8_t)(k | 0x80);\n                extc_buf_flPush(a, half, k);\n            }\n            a->startQ[b] = 1;\n            a->ordQ[b] = (uint8_t)k;   /* allocated: the order, without the free bit */\n#if EXTC_BUF_MMAP_OK\n            if ((((size_t)1 << k) << EXTC_BUF_QSHIFT) >= (size_t)EXTC_BUF_HUGE_MIN)\n                (void)madvise((void *)(a->base + ((size_t)b << EXTC_BUF_QSHIFT)), ((size_t)1 << k) << EXTC_BUF_QSHIFT, MADV_HUGEPAGE);   /* advise the range, never the arena */\n#endif\n            extc_buf_liveBytes += (long long)(((size_t)1 << k) << EXTC_BUF_QSHIFT);\n            return a->base + ((size_t)b << EXTC_BUF_QSHIFT);\n        }\n        if (extc_buf_arenaNew()) continue;\n        break;\n    }\n    extc_buf_fails++;\n    return (char *)0;\n}\n\n/* Give a carved range back, merging with its buddy while the twin is free. Returns 0 when the\n * address is not the start of a range this arena carved (the caller then uses its own fallback). */\n__attribute__((unused)) static int extc_buf_give(char *p) {\n    size_t span = ((size_t)1 << EXTC_BUF_ORD) << EXTC_BUF_QSHIFT;\n    for (int i = 0; i < extc_buf_nArena; i++) {\n        ExtcBufArena *a = &extc_buf_arena[i];\n        size_t off = (size_t)(p - a->base);\n        int32_t b;\n        int k;\n        if (p < a->base || p >= a->base + span) continue;\n        if ((off & ((((size_t)1 << EXTC_BUF_QSHIFT)) - 1)) != 0) return 0;   /* not a quantum boundary */\n        b = (int32_t)(off >> EXTC_BUF_QSHIFT);\n        if (!a->startQ[b] || (a->ordQ[b] & 0x80) || (a->ordQ[b] & 0x7F) > EXTC_BUF_ORD) return 0;   /* not a live block start */\n        k = (int)(a->ordQ[b] & 0x7F);\n        extc_buf_liveBytes -= (long long)(((size_t)1 << k) << EXTC_BUF_QSHIFT);\n        for (;;) {\n            int32_t buddy;\n            if (k >= EXTC_BUF_ORD) break;\n            buddy = b ^ ((int32_t)1 << k);\n            if (!a->startQ[buddy] || a->ordQ[buddy] != (uint8_t)(k | 0x80)) break;\n            extc_buf_flPop(a, buddy, k);   /* the twin leaves the free list in O(1) */\n            a->startQ[buddy] = 0;\n            a->ordQ[buddy] = 0xFF;         /* not a block start any more: the value must not look like one */\n            if (buddy < b) b = buddy;\n            k++;\n            a->ordQ[b] = (uint8_t)(k | 0x80);\n        }\n        a->ordQ[b] = (uint8_t)(k | 0x80);\n        extc_buf_flPush(a, b, k);\n        return 1;\n    }\n    return 0;\n}\n\n/* The size of the carved range that starts at `at`: the number the arena charged to the ledger,\n * which is also what a buffer reports as its reservation. 0 when `at` is not an arena block\n * start -- a reservation the arena could not serve, whose size only its caller knows. The carve\n * rounds up to a power of two of quanta, so the number here can be larger than the request;\n * a buffer that reported its request instead would understate the address space it holds by up\n * to a factor of two, which is exactly the mistake a leak check cannot afford. */\nint64_t extc_buf_span(uint8_t *at) {\n    size_t span = ((size_t)1 << EXTC_BUF_ORD) << EXTC_BUF_QSHIFT;\n    int64_t out = 0;\n    if (!at) return 0;\n    extc_buf_lockAcq();\n    for (int i = 0; i < extc_buf_nArena; i++) {\n        ExtcBufArena *a = &extc_buf_arena[i];\n        char *p = (char *)at;\n        size_t off;\n        int32_t b;\n        if (p < a->base || p >= a->base + span) continue;\n        off = (size_t)(p - a->base);\n        if ((off & ((((size_t)1 << EXTC_BUF_QSHIFT)) - 1)) != 0) break;\n        b = (int32_t)(off >> EXTC_BUF_QSHIFT);\n        if (a->startQ[b] && !(a->ordQ[b] & 0x80)) out = (int64_t)(((size_t)1 << (a->ordQ[b] & 0x7F)) << EXTC_BUF_QSHIFT);\n        break;\n    }\n    extc_buf_lockRel();\n    return out;\n}\n\n/* Reserve at least bytes of address space, 2 MiB aligned, no page resident. 0 on failure. */\nuint8_t *extc_buf_reserve(uint64_t bytes) {\n    char *p;\n    if (bytes < (size_t)4096) bytes = (size_t)4096;\n    bytes = (bytes + (size_t)4095) & ~(size_t)4095;\n    extc_buf_lockAcq();\n    p = extc_buf_carve(bytes);\n    if (!p) {\n        /* Outside the arenas: a range of its own. The release path recognises it by address. */\n#if EXTC_BUF_MMAP_OK\n        uint8_t *raw = mmap((void *)0, (uint64_t)bytes, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, (int64_t)0);\n        if (raw != (uint8_t *)0 && raw != (uint8_t *)-1) {\n            p = (char *)raw;\n            extc_buf_liveBytes += (long long)bytes;\n        }\n#endif\n    }\n    extc_buf_lockRel();\n    return (uint8_t *)p;\n}\n\n/* Give a reservation back. bytes is the count passed to reserve (page rounded there). */\nint32_t extc_buf_release(uint8_t *at, uint64_t bytes) {\n    int ok;\n    if (!at || bytes == 0) return 0;\n    bytes = (bytes + (size_t)4095) & ~(size_t)4095;\n    extc_buf_lockAcq();\n    ok = extc_buf_give((char *)at);\n    if (!ok) {\n        extc_buf_liveBytes -= (long long)bytes;\n    }\n    extc_buf_lockRel();\n    if (ok) return 0;\n#if EXTC_BUF_MMAP_OK\n    return munmap((void *)at, (uint64_t)bytes);\n#else\n    (void)bytes;\n    return 0;\n#endif\n}\n\n/* Drop the pages of [at, at+bytes) back to the OS, keeping the reservation and the address. */\nint32_t extc_buf_discard(uint8_t *at, uint64_t bytes) {\n    size_t down;\n    if (!at || bytes == 0) return 0;\n    down = (size_t)((uintptr_t)at & (uintptr_t)4095);\n    at -= down;\n    bytes += down;\n    bytes = (bytes + (size_t)4095) & ~(size_t)4095;\n#if EXTC_BUF_MMAP_OK\n    return madvise((void *)at, bytes, MADV_DONTNEED);\n#else\n    (void)at;\n    (void)bytes;\n    return 0;\n#endif\n}\n\n/* Address space currently reserved by live buffers: the one number a leak check needs. */\nint64_t extc_buf_live(void) {\n    long long v;\n    extc_buf_lockAcq();\n    v = extc_buf_liveBytes;\n    extc_buf_lockRel();\n    return (int64_t)v;\n}\n");
}
